<?php require __DIR__.'/ui.php';role(['admin','gerente','vendedor','caixa']);$p=db();if($_SERVER['REQUEST_METHOD']==='POST'){csrf_check();$code=strtoupper(trim($_POST['code']?:substr(bin2hex(random_bytes(6)),0,10)));$p->prepare("INSERT INTO gift_cards(code,initial_balance,current_balance,expires_at)VALUES(?,?,?,?)")->execute([$code,$_POST['amount'],$_POST['amount'],$_POST['expires_at']?:null]);go('giftcards.php');}$rows=$p->query("SELECT * FROM gift_cards ORDER BY id DESC")->fetchAll();page_head('Vale-presente');?><div class="grid g2"><div class="card"><form method="post"><?=csrf_field()?><label>Código (vazio = automático)</label><input name="code"><label>Saldo</label><input type="number" step=".01" name="amount" required><label>Validade</label><input type="date" name="expires_at"><button class="primary">Criar vale</button></form></div><div class="card"><table><tr><th>Código</th><th>Inicial</th><th>Saldo</th><th>Validade</th></tr><?php foreach($rows as $x):?><tr><td><b><?=$x['code']?></b></td><td><?=money($x['initial_balance'])?></td><td><?=money($x['current_balance'])?></td><td><?=$x['expires_at']?></td></tr><?php endforeach;?></table></div></div><?php page_foot();?>